import pytest
from google.protobuf import text_format
from ortools.sat import cp_model_pb2
from ortools.sat.python import cp_model

from optimizer.chunked_model_export import export_model, export_whole_model


@pytest.mark.parametrize("objective", ["integer", "floating", "absent", "empty"])
def test_all_root_fields_unicode_nested_messages_and_hint_order_round_trip(tmp_path, objective):
    # Include fields not generated by the current product model, so adding them
    # later cannot silently lose assumptions, search strategy or symmetry.
    source = cp_model_pb2.CpModelProto(name='架空"\\\n\x00')
    source.variables.add(name='変数"\\\n', domain=[0, 1])
    source.variables.add(name="signed", domain=[-10, 10])
    source.constraints.add(name="enforced", enforcement_literal=[-1]).linear.CopyFrom(
        cp_model_pb2.LinearConstraintProto(vars=[1], coeffs=[-3], domain=[-9, 6])
    )
    source.search_strategy.add(variable_selection_strategy=1).exprs.add(
        vars=[1], coeffs=[1], offset=2
    )
    source.solution_hint.vars.extend([1, 0])
    source.solution_hint.values.extend([-1, 1])
    source.assumptions.extend([-1, 0])
    source.symmetry.permutations.add(support=[0, 1], cycle_sizes=[2])
    source.symmetry.orbitopes.add(num_rows=1, num_cols=2, entries=[0, 1])
    if objective == "integer":
        source.objective.CopyFrom(
            cp_model_pb2.CpObjectiveProto(vars=[1], coeffs=[-7], offset=3, scaling_factor=1)
        )
    elif objective == "floating":
        source.floating_point_objective.CopyFrom(
            cp_model_pb2.FloatObjectiveProto(vars=[1], coeffs=[0.5], offset=0.25, maximize=True)
        )
    elif objective == "empty":
        source.objective.SetInParent()
        source.solution_hint.Clear()
        source.solution_hint.SetInParent()
        source.symmetry.Clear()
        source.symmetry.SetInParent()
    model = cp_model.CpModel()
    assert model.proto.parse_text_format(text_format.MessageToString(source))
    path = tmp_path / "model.pb.txt"
    export_model(path, model.proto, 100_000, chunk_size=1)
    restored = cp_model.CpModel()
    assert restored.proto.parse_text_format(path.read_text())
    assert str(restored.proto) == str(model.proto)
    canonical = cp_model_pb2.CpModelProto()
    text_format.Parse(path.read_text(), canonical)
    assert canonical == source


def test_failed_second_piece_leaves_no_final_or_temporary_files(tmp_path, monkeypatch):
    model = cp_model.CpModel()
    model.new_bool_var("fictional-0")
    model.new_bool_var("fictional-1")
    native = cp_model.CpModel.export_to_file
    calls = []

    def export(part, path):
        calls.append(path)
        return native(part, path) if len(calls) == 1 else False

    monkeypatch.setattr(cp_model.CpModel, "export_to_file", export)
    with pytest.raises(ValueError, match="MODEL_HANDOFF_EXPORT"):
        export_model(tmp_path / "model.pb.txt", model.proto, 100_000, chunk_size=1)
    assert len(calls) == 2 and not list(tmp_path.iterdir())


def test_size_limit_keeps_unfinished_model_unavailable(tmp_path):
    model = cp_model.CpModel()
    model.new_bool_var("fictional")
    with pytest.raises(ValueError, match="MODEL_HANDOFF_LIMIT"):
        export_model(tmp_path / "model.pb.txt", model.proto, 1)
    assert not list(tmp_path.iterdir())


def test_existing_destination_is_not_overwritten(tmp_path):
    path = tmp_path / "model.pb.txt"
    path.write_text("owned-existing")
    with pytest.raises(ValueError, match="MODEL_HANDOFF_EXPORT_PATH"):
        export_model(path, cp_model.CpModel().proto, 100_000)
    assert path.read_text() == "owned-existing"


@pytest.mark.parametrize("size", [0, -1, True, 20_001])
def test_unbounded_or_invalid_piece_count_is_rejected(tmp_path, size):
    with pytest.raises(ValueError, match="MODEL_HANDOFF_CHUNK_SIZE"):
        export_model(tmp_path / "model.pb.txt", cp_model.CpModel().proto, 100_000, chunk_size=size)
    assert not list(tmp_path.iterdir())


@pytest.mark.parametrize("failure", ["limit", "native", "existing"])
def test_whole_export_does_not_promote_failed_or_overwrite_existing_file(
    tmp_path, monkeypatch, failure
):
    model = cp_model.CpModel()
    model.new_bool_var("fictional")
    path = tmp_path / "model.pb.txt"
    if failure == "native":
        monkeypatch.setattr(cp_model.CpModel, "export_to_file", lambda *args: False)
    if failure == "existing":
        path.write_text("owned-existing")
    with pytest.raises(ValueError, match="MODEL_HANDOFF_"):
        export_whole_model(path, model, 1 if failure == "limit" else 100_000)
    assert not (tmp_path / "model.pb.txt.pending.txt").exists()
    assert list(tmp_path.iterdir()) == ([path] if failure == "existing" else [])
    if failure == "existing":
        assert path.read_text() == "owned-existing"
